<?php
namespace App\Http\Requests\Resident;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;
class StoreReportRequest extends FormRequest { public function authorize():bool{return $this->user()?->role==='resident';} public function rules():array{return ['category_id'=>['required',Rule::exists('report_categories','id')->where('is_active',true)],'purok_id'=>['required',Rule::exists('puroks','id')->where('is_active',true)],'title'=>['required','string','min:5','max:150'],'description'=>['required','string','min:30','max:3000'],'photos'=>['required','array','min:1','max:5'],'photos.*'=>['required','file','image','mimes:jpg,jpeg,png,webp','max:5120'],'latitude'=>['required','numeric','between:-90,90'],'longitude'=>['required','numeric','between:-180,180'],'location_notes'=>['nullable','string','max:500'],'submission_token'=>['required','uuid',Rule::unique('reports','submission_token')],'confirm_accuracy'=>['accepted']];} public function messages():array{return ['photos.required'=>'Add at least one supporting photo.','description.min'=>'Describe the concern in at least 30 characters.','latitude.required'=>'Select the report location on the map.','confirm_accuracy.accepted'=>'Confirm that the report information is accurate.'];} }
